from pwn import *
import time
import json
from collections import defaultdict
import statistics

# Configure logging
context.log_level = 'debug'

class RouletteAnalyzer:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.data = {
            'games': [],
            'other_players': defaultdict(list),
            'outcomes': {'red': 0, 'black': 0, 'green': 0},
            'timestamps': []
        }

    def parse_others_results(self, data):
        # Look for patterns like "Player X bet Y on Z and won/lost"
        if "bet" in data.lower() and ("won" in data.lower() or "lost" in data.lower()):
            parts = data.split()
            try:
                player = parts[0]
                bet_amount = int(''.join(c for c in parts[2] if c.isdigit()))
                result = "won" if "won" in data.lower() else "lost"
                self.data['other_players'][player].append({
                    'bet': bet_amount,
                    'result': result,
                    'timestamp': time.time()
                })
            except:
                pass

    def play_round(self, conn):
        game_data = {
            'timestamp': time.time(),
            'bet_amount': 1,
            'outcome': None,
            'result': None
        }

        # Wait for initial prompt
        while True:
            try:
                line = conn.recvline().decode('utf-8').strip()
                if "Current balance:" in line:
                    break
                self.parse_others_results(line)
            except:
                break

        # Place minimum bet
        conn.sendline(b"1")

        # Choose red (consistent choice for pattern analysis)
        conn.sendline(b"red")

        # Get outcome
        while True:
            try:
                line = conn.recvline().decode('utf-8').strip()
                if "won" in line.lower():
                    game_data['result'] = 'won'
                    game_data['outcome'] = 'red'
                    self.data['outcomes']['red'] += 1
                    break
                elif "lost" in line.lower():
                    game_data['result'] = 'lost'
                    # Try to determine actual outcome
                    if "black" in line.lower():
                        game_data['outcome'] = 'black'
                        self.data['outcomes']['black'] += 1
                    elif "green" in line.lower():
                        game_data['outcome'] = 'green'
                        self.data['outcomes']['green'] += 1
                    break
                self.parse_others_results(line)
            except:
                break

        self.data['games'].append(game_data)
        self.data['timestamps'].append(game_data['timestamp'])

    def analyze_patterns(self):
        # Basic statistics
        stats = {
            'total_games': len(self.data['games']),
            'outcomes': dict(self.data['outcomes']),
            'win_rate': sum(1 for g in self.data['games'] if g['result'] == 'won') / len(self.data['games']),
            'other_players': len(self.data['other_players']),
            'avg_time_between_games': 0
        }

        # Calculate average time between games
        if len(self.data['timestamps']) > 1:
            time_diffs = [j-i for i, j in zip(self.data['timestamps'][:-1], self.data['timestamps'][1:])]
            stats['avg_time_between_games'] = statistics.mean(time_diffs)

        # Check for patterns in outcomes
        outcomes = [g['outcome'] for g in self.data['games'] if g['outcome']]
        patterns = defaultdict(int)
        for i in range(len(outcomes)-2):
            pattern = f"{outcomes[i]}-{outcomes[i+1]}-{outcomes[i+2]}"
            patterns[pattern] += 1

        stats['common_patterns'] = dict(sorted(patterns.items(), key=lambda x: x[1], reverse=True)[:3])

        return stats

    def run(self, rounds=50):
        conn = remote(self.host, self.port)

        for _ in range(rounds):
            try:
                self.play_round(conn)
                # Small delay to avoid overwhelming the server
                time.sleep(0.5)
            except:
                # Reconnect if connection fails
                conn = remote(self.host, self.port)

        conn.close()
        return self.analyze_patterns()

def main():
    analyzer = RouletteAnalyzer('rev.chal.csaw.io', 4200)
    print("Starting roulette analysis...")
    stats = analyzer.run(rounds=50)
    print("\nAnalysis Results:")
    print(json.dumps(stats, indent=2))

    # Save data to file for further analysis
    with open('roulette_data.json', 'w') as f:
        json.dump(analyzer.data, f, indent=2, default=str)

if __name__ == "__main__":
    main()

