import java.io.*;
import java.net.*;
import java.util.*;
import java.nio.file.*;

public class RouletteClassCapture {
    private static final String HOST = "rev.chal.csaw.io";
    private static final int PORT = 4200;

    public static void main(String[] args) {
        try {
            // Create a raw socket to capture all data
            Socket socket = new Socket(HOST, PORT);
            InputStream rawIn = socket.getInputStream();
            OutputStream rawOut = socket.getOutputStream();

            // Buffer to store potential class file data
            ByteArrayOutputStream classData = new ByteArrayOutputStream();
            byte[] buffer = new byte[8192];

            // Send initial connection data
            String init = "25\ngreen\n";
            rawOut.write(init.getBytes());
            rawOut.flush();

            // Read response and look for class file magic number (0xCAFEBABE)
            int bytesRead;
            boolean foundClass = false;

            while ((bytesRead = rawIn.read(buffer)) != -1) {
                for (int i = 0; i < bytesRead - 3; i++) {
                    // Look for Java class file magic number
                    if (buffer[i] == (byte)0xCA && 
                        buffer[i+1] == (byte)0xFE && 
                        buffer[i+2] == (byte)0xBA && 
                        buffer[i+3] == (byte)0xBE) {

                        System.out.println("Found Java class file signature at offset " + i);

                        // Write from magic number onwards
                        classData.write(buffer, i, bytesRead - i);
                        foundClass = true;

                        // Write to file
                        Files.write(Paths.get("captured.class"), classData.toByteArray());
                        System.out.println("Wrote class data to captured.class");
                        break;
                    }
                }

                if (!foundClass) {
                    // Store the data for analysis
                    classData.write(buffer, 0, bytesRead);
                }

                // Print received data as hex for analysis
                System.out.println("Received data (hex):");
                for (int i = 0; i < bytesRead; i++) {
                    System.out.printf("%02X ", buffer[i]);
                    if ((i + 1) % 16 == 0) System.out.println();
                }
                System.out.println();
            }

            socket.close();

        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

