from pwn import *
import time
import random

# Connect to the roulette server
def connect_to_server():
    return remote('rev.chal.csaw.io', 4200)

# Function to parse server response
def parse_response(r):
    try:
        data = r.recvuntil(b'Choice:').decode()
        return data
    except:
        return None

# Function to make a bet
def place_bet(r, amount, color):
    r.sendline(b'1')  # Select bet option
    r.recvuntil(b'Amount:')
    r.sendline(str(amount).encode())
    r.recvuntil(b'Color (R/B/G):')
    r.sendline(color.encode())
    return parse_response(r)

# Function to predict next color based on seed
def predict_color(seed):
    random.seed(seed)
    val = random.randint(0, 36)
    if val == 0:
        return 'G'
    elif val % 2 == 0:
        return 'R'
    else:
        return 'B'

def main():
    wins = 0
    required_wins = 20

    while wins < required_wins:
        try:
            # Connect with precise timing
            curr_time = int(time.time())
            r = connect_to_server()

            # Make initial small bet to observe outcome
            response = place_bet(r, 1, 'R')
            if not response:
                r.close()
                continue

            # Try different seeds around current time
            for seed_offset in range(-5, 5):
                test_seed = curr_time + seed_offset
                predicted = predict_color(test_seed)

                # If we find a matching prediction, use it for next bets
                if predicted in response and "WIN" in response:
                    log.info(f"Found likely seed: {test_seed}")

                    # Now place larger bets on predicted greens
                    for _ in range(5):  # Try up to 5 bets per connection
                        next_seed = test_seed + 1
                        prediction = predict_color(next_seed)

                        if prediction == 'G':
                            response = place_bet(r, 100, 'G')
                            if "WIN" in response:
                                wins += 1
                                log.success(f"Won bet! Wins: {wins}/{required_wins}")
                                if wins >= required_wins:
                                    # Try to get flag
                                    r.sendline(b'2')  # Check balance option
                                    flag = r.recvall(timeout=2)
                                    print(flag.decode())
                                    return
                            else:
                                break
                        test_seed = next_seed

            r.close()
            time.sleep(1)  # Brief pause between attempts

        except Exception as e:
            log.error(f"Error occurred: {e}")
            continue

